import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import hashlib
import time

app = Flask(__name__)

UPLOAD_DIR = '/tmp/conversions'
ALLOWED_EXTENSIONS = {'doc', 'docx', 'odt', 'rtf', 'txt'}
MAX_FILE_SIZE = 10 * 1024 * 1024  # 10MB

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def generate_job_id(filename):
    return hashlib.md5(f"{filename}{time.time()}".encode()).hexdigest()[:12]

@app.route('/health', methods=['GET'])
def health():
    return jsonify({"status": "ok", "version": "2.1.4"})

@app.route('/convert', methods=['POST'])
def convert_document():
    if 'file' not in request.files:
        return jsonify({"error": "No file provided"}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({"error": "Empty filename"}), 400

    if not allowed_file(file.filename):
        return jsonify({"error": "File type not allowed"}), 400

    output_format = request.form.get('format', 'pdf')

    # Validate output format
    valid_formats = ['pdf', 'html', 'epub', 'txt']
    if output_format not in valid_formats:
        return jsonify({"error": f"Invalid format. Use: {valid_formats}"}), 400

    filename = secure_filename(file.filename)
    job_id = generate_job_id(filename)

    os.makedirs(UPLOAD_DIR, exist_ok=True)
    input_path = os.path.join(UPLOAD_DIR, f"{job_id}_{filename}")
    file.save(input_path)

    # Check file size after save
    if os.path.getsize(input_path) > MAX_FILE_SIZE:
        os.remove(input_path)
        return jsonify({"error": "File too large"}), 413

    output_filename = f"{job_id}_output.{output_format}"
    output_path = os.path.join(UPLOAD_DIR, output_filename)

    # Page range parameter for selective conversion
    page_range = request.form.get('pages', '')

    # Build conversion command
    cmd = f"libreoffice --headless --convert-to {output_format}"

    if page_range:
        # User-specified page range passed to conversion filter
        cmd += f" --infilter='PageRange={page_range}'"

    cmd += f" --outdir {UPLOAD_DIR} {input_path}"

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=120,
            cwd=UPLOAD_DIR
        )

        if result.returncode != 0:
            return jsonify({
                "error": "Conversion failed",
                "details": result.stderr.decode('utf-8', errors='replace')[:200]
            }), 500

        # LibreOffice names output based on input filename
        expected_output = os.path.join(
            UPLOAD_DIR, 
            f"{job_id}_{os.path.splitext(filename)[0]}.{output_format}"
        )

        if os.path.exists(expected_output):
            return send_file(expected_output, as_attachment=True, download_name=output_filename)
        else:
            return jsonify({"error": "Output file not generated"}), 500

    except subprocess.TimeoutExpired:
        return jsonify({"error": "Conversion timed out"}), 504
    finally:
        # Cleanup input file
        if os.path.exists(input_path):
            os.remove(input_path)

@app.route('/batch', methods=['POST'])
def batch_convert():
    """Convert multiple files. Accepts JSON with base64-encoded files."""
    data = request.get_json()
    if not data or 'files' not in data:
        return jsonify({"error": "No files in request"}), 400

    if len(data['files']) > 5:
        return jsonify({"error": "Maximum 5 files per batch"}), 400

    return jsonify({"error": "Batch endpoint temporarily disabled"}), 503

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
